{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "U-47700, a tertiary amide with a basic amine, was detected in zebrafish brain after only 20 min exposure, directly demonstrating BBB penetration for a structurally related amide-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "PET imaging in rhesus monkeys showed high brain uptake of a related heteroaryl amide, with SUV values above 3.8 in multiple brain regions, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "JNJ-39393406, a heteroaryl amide CNS agent, produced CSF concentration-time profiles very similar to plasma in humans, providing direct translational evidence for CNS penetration in this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A related heteroaryl amide PET tracer reached about 5 %ID/cc in mouse brain within 5 minutes, confirming good brain penetration for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Biarylamide analogues with heteroaromatic and amide features traversed the BBB and achieved excellent mouse brain drug levels after oral dosing, supporting the query's CNS access potential.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer experimental evidence points to meaningful BBB penetration for amide/heteroaryl molecules closely related to the query. Direct brain, CSF, PET, and rodent brain-level measurements consistently support a pass prediction.",
  "evidence_gaps": [
